function updateIncomingRay(lightVec) {
  const incomingDir = lightVec.clone().multiplyScalar(-1);
  const coneH = 0.38;
  const startDist = 4.2;
  const endDist = coneH;
  const span = startDist - endDist;
  for (let i = 0; i < incomingSegments.length; i++) {
    const t0 = i / incomingSegments.length;
    const t1 = (i + 1) / incomingSegments.length;
    const d0 = startDist - span * t0;
    const d1 = startDist - span * t1;
    const len = d0 - d1;
    const mid = (d0 + d1) / 2;
    const seg = incomingSegments[i];
    seg.position.copy(lightVec).multiplyScalar(mid);
    seg.scale.set(1, len, 1);
    orientAlongY(seg, incomingDir);
  }
  incomingCone.position.copy(lightVec).multiplyScalar(coneH / 2);
  orientAlongY(incomingCone, incomingDir);
}

function updateBRDFLobe(lightVecGlobal) {
  frameGroup.updateMatrixWorld(true);
  const invQ = frameGroup.quaternion.clone().invert();
  const lightLocal = lightVecGlobal.clone().applyQuaternion(invQ).normalize();
  if (lightLocal.y < 0.03) {
    lightLocal.y = 0.03;
    lightLocal.normalize();
  }

  const mirrorLocal = new THREE.Vector3(-lightLocal.x, lightLocal.y, -lightLocal.z).normalize();
  if (mirrorLocal.y < 0.03) {
    mirrorLocal.y = 0.03;
    mirrorLocal.normalize();
  }

  const type = brdfTypeInput.value;
  for (let i = 0; i < outgoingArrows.length; i++) {
    const dir = outgoingDirs[i];
    let len;
    if (type === 'Specular (Glossy Phong)') {
      const c = Math.max(0, dir.dot(mirrorLocal));
      len = 0.22 + 1.18 * Math.pow(c, 18);
    } else if (type === 'Retroreflective') {
      const c = Math.max(0, dir.dot(lightLocal));
      len = 0.20 + 1.22 * Math.pow(c, 18);
    } else {
      len = 0.72;
    }
    setArrow(outgoingArrows[i], dir, len);
  }

  let primaryDir;
  if (type === 'Specular (Glossy Phong)') {
    primaryDir = mirrorLocal;
  } else if (type === 'Retroreflective') {
    primaryDir = lightLocal;
  } else {
    primaryDir = new THREE.Vector3(0.63, 0.72, 0.28).normalize();
  }
  setArrow(primaryOutArrow, primaryDir, 2.15);
}

