function makeArrow(color, radius = 0.025, coneRadius = 0.09, coneHeight = 0.24, opacity = 1) {
  const group = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 0.98
  });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 18), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(coneRadius, coneHeight, 28), mat);
  group.add(shaft, head);
  group.userData.shaft = shaft;
  group.userData.head = head;
  group.userData.coneHeight = coneHeight;
  group.userData.dir = new THREE.Vector3(0, 1, 0);
  group.userData.len = 1;
  return group;
}

function setArrow(group, direction, length, start = new THREE.Vector3(0, 0, 0)) {
  const dir = direction.clone().normalize();
  const coneH = group.userData.coneHeight;
  const shaftLen = Math.max(0.01, length - coneH);
  group.position.copy(start);
  group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.userData.shaft.scale.set(1, shaftLen, 1);
  group.userData.shaft.position.set(0, shaftLen / 2, 0);
  group.userData.head.position.set(0, shaftLen + coneH / 2, 0);
  group.userData.dir.copy(dir);
  group.userData.len = length;
}

