let currentStep = 0;
let tweenToken = 0;

function setStepText(i) {
  const step = brdfSteps[i];
  stepTitle.textContent = step.title;
  stepNarration.textContent = step.narration;
  for (let j = 0; j < brdfSteps.length; j++) {
    const b = document.getElementById(`btnStep${j}`);
    if (b) b.classList.toggle('active', j === i);
  }
}

function applyStateImmediate(state) {
  lightElevationInput.value = state.lightElevation;
  lightAzimuthInput.value = state.lightAzimuth;
  normalTiltInput.value = state.normalTilt;
  brdfTypeInput.value = state.brdfType;
  updateScene();
}

function goToStep(index) {
  currentStep = (index + brdfSteps.length) % brdfSteps.length;
  const step = brdfSteps[currentStep];
  setStepText(currentStep);

  const token = ++tweenToken;
  const start = {
    lightElevation: Number(lightElevationInput.value),
    lightAzimuth: Number(lightAzimuthInput.value),
    normalTilt: Number(normalTiltInput.value)
  };
  const target = step.state;
  brdfTypeInput.value = target.brdfType;
  const t0 = performance.now();
  const dur = 650;

  function tick(now) {
    if (token !== tweenToken) return;
    const u0 = Math.min(1, (now - t0) / dur);
    const u = u0 * u0 * (3 - 2 * u0);
    lightElevationInput.value = start.lightElevation + (target.lightElevation - start.lightElevation) * u;
    lightAzimuthInput.value = start.lightAzimuth + (target.lightAzimuth - start.lightAzimuth) * u;
    normalTiltInput.value = start.normalTilt + (target.normalTilt - start.normalTilt) * u;
    updateScene();
    if (u0 < 1) requestAnimationFrame(tick);
    else applyStateImmediate(target);
  }
  requestAnimationFrame(tick);
}

window.goToStep = goToStep;

document.getElementById('btnPrevStep').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('btnNextStep').addEventListener('click', () => goToStep(currentStep + 1));
for (let i = 0; i < brdfSteps.length; i++) {
  document.getElementById(`btnStep${i}`).addEventListener('click', () => goToStep(i));
}
setStepText(0);
